WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('MONTH', prev_txn_time) AS activity_month, SUM(CASE WHEN merchant = 'Grab' THEN session_no ELSE 0 END) AS grab_session_no, SUM(CASE WHEN txn_type = 'DEBIT' THEN session_no ELSE 0 END) AS debit_session_no, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst FROM sessionized GROUP BY DATE_TRUNC('MONTH', prev_txn_time) HAVING ROUND(AVG(is_new_burst), 2) > 0;
